sa_mode_t cur_mode;
sa_mode_t next_mode;
int config_ok = 1;
int rejected = 0;
int enable_ok;
adcs_vec3_t measured, target;
adcs_vec3_t cross_v;
adcs_vec3_t axis;
double dot_v;
double angle = 0.0;
double gain;
double torque_mag;
double dn;
double vals[3];
double prev_vals[3];
double delta;
size_t i;

cur_mode = sa_state.mode;
sa_output.mode = cur_mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;
sa_output.error_rad = 0.0;
sa_output.rotation_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
sa_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
sa_output.slew_mask = 0U;

if ((sa_config.enter_rad < 0.0) || (sa_config.enter_rad >= sa_config.exit_rad) ||
    (sa_config.exit_rad > ADCS_PI) || (sa_config.acquire_gain_nm_rad < 0.0) ||
    (sa_config.track_gain_nm_rad < 0.0) || (!(sa_config.torque_limit_nm > 0.0)) ||
    (!(sa_config.max_slew_nm_per_cycle > 0.0)) || (sa_config.coast_decay < 0.0) ||
    (sa_config.coast_decay > 1.0) || (sa_config.acquire_samples < 1U) ||
    (sa_config.acquire_samples > 20U) || (sa_config.max_coast_samples < 1U) ||
    (sa_config.max_coast_samples >= sa_config.max_bad_samples) ||
    (sa_config.max_bad_samples > 20U))
    config_ok = 0;

enable_ok = (sa_input.enable == 0) || (sa_input.enable == 1);
if ((!enable_ok) || ((sa_input.valid != 0) && (sa_input.valid != 1)))
    config_ok = 0;

if (sa_input.enable == 0) {
    sa_state.mode = SA_OFF;
    sa_state.good_samples = 0U;
    sa_state.bad_samples = 0U;
    sa_state.coast_samples = 0U;
    sa_state.previous_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    sa_output.mode = SA_OFF;
    sa_output.good_samples = 0U;
    sa_output.bad_samples = 0U;
    sa_output.coast_samples = 0U;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    sa_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    sa_output.slew_mask = 0U;
    return;
}

if ((!config_ok) || (sa_input.valid == 0) || (sa_input.measured_body == NULL) ||
    (sa_input.target_body == NULL) ||
    (!adcs_is_finite_vec3(sa_input.measured_body)) ||
    (!adcs_is_finite_vec3(sa_input.target_body)))
    rejected = 1;

if (!rejected) {
    if (adcs_vec3_normalize(sa_input.measured_body, ADCS_EPS_NORM, &measured) != ADCS_OK)
        rejected = 1;
    else if (adcs_vec3_normalize(sa_input.target_body, ADCS_EPS_NORM, &target) != ADCS_OK)
        rejected = 1;
}

if (rejected) {
    sa_state.good_samples = 0U;
    sa_state.bad_samples += 1U;

    if (((cur_mode == SA_TRACK) || (cur_mode == SA_COAST)) &&
        (sa_state.coast_samples < sa_config.max_coast_samples)) {
        sa_state.coast_samples += 1U;
        next_mode = SA_COAST;
        sa_output.torque_nm = adcs_vec3_scale(&sa_state.previous_torque_nm,
                                              sa_config.coast_decay);
        sa_state.mode = next_mode;
        sa_output.mode = next_mode;
        sa_output.good_samples = sa_state.good_samples;
        sa_output.bad_samples = sa_state.bad_samples;
        sa_output.coast_samples = sa_state.coast_samples;
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
        sa_output.slew_mask = 0U;
        if (sa_state.bad_samples >= sa_config.max_bad_samples) {
            sa_state.mode = SA_FAULT;
            sa_output.mode = SA_FAULT;
        }
        return;
    }

    if (sa_state.bad_samples >= sa_config.max_bad_samples) {
        sa_state.mode = SA_FAULT;
        sa_output.mode = SA_FAULT;
        sa_output.bad_samples = sa_state.bad_samples;
        sa_output.good_samples = sa_state.good_samples;
        sa_output.coast_samples = sa_state.coast_samples;
        sa_output.torque_nm = sa_state.previous_torque_nm;
        return;
    }

    sa_output.mode = cur_mode;
    sa_output.bad_samples = sa_state.bad_samples;
    sa_output.good_samples = sa_state.good_samples;
    sa_output.coast_samples = sa_state.coast_samples;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    sa_output.torque_nm = sa_state.previous_torque_nm;
    sa_output.slew_mask = 0U;
    return;
}

sa_state.good_samples += 1U;
sa_state.bad_samples = 0U;

dot_v = adcs_vec3_dot(&measured, &target);
cross_v = adcs_vec3_cross(&measured, &target);
angle = atan2(adcs_vec3_norm(&cross_v), dot_v);

if (angle >= ADCS_PI - ADCS_EPS_COLLINEAR) {
    double ax = fabs(measured.x);
    double ay = fabs(measured.y);
    double az = fabs(measured.z);
    adcs_vec3_t basis;
    if ((ax <= ay) && (ax <= az))
        basis = (adcs_vec3_t){1.0, 0.0, 0.0};
    else if (ay <= az)
        basis = (adcs_vec3_t){0.0, 1.0, 0.0};
    else
        basis = (adcs_vec3_t){0.0, 0.0, 1.0};
    axis = adcs_vec3_cross(&measured, &basis);
    dn = adcs_vec3_norm(&axis);
    if (dn > ADCS_EPS_NORM)
        axis = adcs_vec3_scale(&axis, 1.0 / dn);
    else
        axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    angle = ADCS_PI;
} else if (adcs_vec3_norm(&cross_v) > ADCS_EPS_NORM) {
    dn = adcs_vec3_norm(&cross_v);
    axis = adcs_vec3_scale(&cross_v, 1.0 / dn);
} else {
    axis = (adcs_vec3_t){0.0, 0.0, 0.0};
}

next_mode = cur_mode;
switch (cur_mode) {
case SA_OFF:
case SA_SEARCH:
    if (angle <= sa_config.enter_rad)
        next_mode = SA_ACQUIRE;
    break;
case SA_ACQUIRE:
    if (angle <= sa_config.enter_rad) {
        if (sa_state.good_samples >= sa_config.acquire_samples)
            next_mode = SA_TRACK;
    } else {
        sa_state.good_samples = 0U;
        next_mode = SA_SEARCH;
    }
    break;
case SA_TRACK:
    if (angle >= sa_config.exit_rad)
        next_mode = SA_SEARCH;
    break;
case SA_COAST:
    sa_state.coast_samples = 0U;
    if (angle < sa_config.exit_rad)
        next_mode = SA_TRACK;
    else
        next_mode = SA_SEARCH;
    break;
case SA_FAULT:
default:
    next_mode = SA_FAULT;
    break;
}

if (next_mode != SA_COAST)
    sa_state.coast_samples = 0U;

sa_state.mode = next_mode;

if ((next_mode == SA_TRACK) || (next_mode == SA_COAST))
    gain = sa_config.track_gain_nm_rad;
else
    gain = sa_config.acquire_gain_nm_rad;

torque_mag = gain * angle;
if (torque_mag > sa_config.torque_limit_nm)
    torque_mag = sa_config.torque_limit_nm;

vals[0] = torque_mag * axis.x;
vals[1] = torque_mag * axis.y;
vals[2] = torque_mag * axis.z;

prev_vals[0] = sa_state.previous_torque_nm.x;
prev_vals[1] = sa_state.previous_torque_nm.y;
prev_vals[2] = sa_state.previous_torque_nm.z;

sa_output.slew_mask = 0U;
for (i = 0; i < 3U; i++) {
    delta = vals[i] - prev_vals[i];
    if (delta > sa_config.max_slew_nm_per_cycle) {
        delta = sa_config.max_slew_nm_per_cycle;
        sa_output.slew_mask |= (unint32)(1U << i);
    } else if (delta < -sa_config.max_slew_nm_per_cycle) {
        delta = -sa_config.max_slew_nm_per_cycle;
        sa_output.slew_mask |= (unint32)(1U << i);
    }
    vals[i] = prev_vals[i] + delta;
}

sa_state.previous_torque_nm = (adcs_vec3_t){vals[0], vals[1], vals[2]};
sa_output.torque_nm = sa_state.previous_torque_nm;
sa_output.mode = next_mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;
sa_output.error_rad = angle;
sa_output.rotation_axis = axis;

