sa_state.mode = mode;
sa_state.previous_torque_nm = torque;

sa_output.mode = mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;
sa_output.error_rad = angle;
sa_output.rotation_axis = axis;
sa_output.torque_nm = torque;
sa_output.slew_mask = slew_mask;

candidates.misra:
adcs_vec3_t unit_m, unit_t, axis, torque, prev;
double dot, cross_norm, angle, gain, mag, scale, delta, comp;
uint32_t slew_mask;
int cfg_ok, flags_ok, accepted;
sa_mode_t mode;

/* --- step 1: configuration validation --- */
cfg_ok = 1;
if ((sa_config.enter_rad < 0.0) || (sa_config.exit_rad > ADCS_PI) ||
    (!(sa_config.enter_rad < sa_config.exit_rad)))
    cfg_ok = 0;
if ((sa_config.acquire_gain_nm_rad < 0.0) || (sa_config.track_gain_nm_rad < 0.0))
    cfg_ok = 0;
if (!(sa_config.torque_limit_nm > 0.0) || !(sa_config.max_slew_nm_per_cycle > 0.0))
    cfg_ok = 0;
if ((sa_config.coast_decay < 0.0) || (sa_config.coast_decay > 1.0))
    cfg_ok = 0;
if ((sa_config.acquire_samples < 1U) || (sa_config.acquire_samples > 20U))
    cfg_ok = 0;
if ((sa_config.max_coast_samples < 1U) ||
    (!(sa_config.max_coast_samples < sa_config.max_bad_samples)) ||
    (sa_config.max_bad_samples > 20U))
    cfg_ok = 0;

/* --- step 2: flag/binary and input validity --- */
flags_ok = (int)(((sa_input.enable == 0) || (sa_input.enable == 1)) &&
                 ((sa_input.valid == 0) || (sa_input.valid == 1)));

accepted = (int)(cfg_ok && flags_ok && (sa_input.valid == 1) &&
                 (sa_input.measured_body != NULL) && (sa_input.target_body != NULL) &&
                 adcs_is_finite_vec3(sa_input.measured_body) &&
                 adcs_is_finite_vec3(sa_input.target_body));

if (accepted) {
    if (adcs_vec3_normalize(sa_input.measured_body, ADCS_EPS_NORM, &unit_m) != ADCS_OK)
        accepted = 0;
    else if (adcs_vec3_normalize(sa_input.target_body, ADCS_EPS_NORM, &unit_t) != ADCS_OK)
        accepted = 0;
    else {
        /* both vectors normalized successfully; accepted remains true */
    }
}

/* --- step 3: disable or non-binary flag resets all state --- */
if ((flags_ok == 0) || (sa_input.enable == 0)) {
    sa_state.mode = SA_OFF;
    sa_state.good_samples = 0U;
    sa_state.bad_samples = 0U;
    sa_state.coast_samples = 0U;
    sa_state.previous_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    sa_output.mode = SA_OFF;
    sa_output.good_samples = 0U;
    sa_output.bad_samples = 0U;
    sa_output.coast_samples = 0U;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    sa_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
    sa_output.slew_mask = 0U;
    return;
}

/* --- step 4: rejected sample handling --- */
if (!accepted) {
    sa_state.good_samples = 0U;
    sa_state.bad_samples += 1U;

    if (cfg_ok &&
        ((sa_state.mode == SA_TRACK) || (sa_state.mode == SA_COAST)) &&
        (sa_state.coast_samples < sa_config.max_coast_samples)) {
        sa_state.coast_samples += 1U;
        sa_state.mode = SA_COAST;
        torque.x = sa_state.previous_torque_nm.x * sa_config.coast_decay;
        torque.y = sa_state.previous_torque_nm.y * sa_config.coast_decay;
        torque.z = sa_state.previous_torque_nm.z * sa_config.coast_decay;
        sa_state.previous_torque_nm = torque;
        sa_output.mode = SA_COAST;
        sa_output.good_samples = sa_state.good_samples;
        sa_output.bad_samples = sa_state.bad_samples;
        sa_output.coast_samples = sa_state.coast_samples;
        sa_output.torque_nm = torque;
        sa_output.slew_mask = 0U;
        return;
    }

    if (sa_state.bad_samples >= sa_config.max_bad_samples) {
        sa_state.mode = SA_FAULT;
        sa_state.previous_torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        sa_output.mode = SA_FAULT;
        sa_output.good_samples = sa_state.good_samples;
        sa_output.bad_samples = sa_state.bad_samples;
        sa_output.coast_samples = sa_state.coast_samples;
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
        sa_output.torque_nm = (adcs_vec3_t){0.0, 0.0, 0.0};
        sa_output.slew_mask = 0U;
        return;
    }

    sa_output.mode = sa_state.mode;
    sa_output.good_samples = sa_state.good_samples;
    sa_output.bad_samples = sa_state.bad_samples;
    sa_output.coast_samples = sa_state.coast_samples;
    sa_output.torque_nm = sa_state.previous_torque_nm;
    sa_output.slew_mask = 0U;
    return;
}

/* --- step 5: accepted sample geometry --- */
sa_state.bad_samples = 0U;

dot = adcs_vec3_dot(&unit_m, &unit_t);
axis = adcs_vec3_cross(&unit_m, &unit_t);
cross_norm = adcs_vec3_norm(&axis);

if (cross_norm <= ADCS_EPS_COLLINEAR) {
    if (dot > 0.0) {
        axis = (adcs_vec3_t){0.0, 0.0, 0.0};
        angle = 0.0;
    } else {
        adcs_vec3_t basis;
        double ax, ay, az;
        ax = fabs(unit_m.x);
        ay = fabs(unit_m.y);
        az = fabs(unit_m.z);
        if ((ax <= ay) && (ax <= az))
            basis = (adcs_vec3_t){1.0, 0.0, 0.0};
        else if (ay <= az)
            basis = (adcs_vec3_t){0.0, 1.0, 0.0};
        else
            basis = (adcs_vec3_t){0.0, 0.0, 1.0};
        axis = adcs_vec3_cross(&unit_m, &basis);
        (void)adcs_vec3_normalize(&axis, ADCS_EPS_NORM, &axis);
        angle = ADCS_PI;
    }
} else {
    axis = adcs_vec3_scale(&axis, 1.0 / cross_norm);
    angle = atan2(cross_norm, dot);
}

mode = sa_state.mode;

/* --- step 6: mode transitions on accepted sample --- */
if (mode == SA_OFF)
    mode = SA_SEARCH;

if (mode == SA_SEARCH) {
    if (angle <= sa_config.enter_rad) {
        mode = SA_ACQUIRE;
        sa_state.good_samples = 1U;
    } else {
        sa_state.good_samples = 0U;
    }
} else if (mode == SA_ACQUIRE) {
    if (angle <= sa_config.enter_rad) {
        sa_state.good_samples += 1U;
        if (sa_state.good_samples >= sa_config.acquire_samples)
            mode = SA_TRACK;
    } else {
        mode = SA_SEARCH;
        sa_state.good_samples = 0U;
    }
} else if (mode == SA_TRACK) {
    if (angle >= sa_config.exit_rad)
        mode = SA_SEARCH;
} else if (mode == SA_COAST) {
    sa_state.coast_samples = 0U;
    if (angle < sa_config.exit_rad)
        mode = SA_TRACK;
    else
        mode = SA_SEARCH;
} else {
    mode = SA_SEARCH;
}

/* --- step 7: gain from post-transition mode --- */
if ((mode == SA_SEARCH) || (mode == SA_ACQUIRE))
    gain = sa_config.acquire_gain_nm_rad;
else
    gain = sa_config.track_gain_nm_rad;

torque = adcs_vec3_scale(&axis, gain * angle);

/* --- step 8: torque magnitude limit --- */
mag = adcs_vec3_norm(&torque);
if (mag > sa_config.torque_limit_nm) {
    scale = sa_config.torque_limit_nm / mag;
    torque = adcs_vec3_scale(&torque, scale);
}

/* --- step 9: slew limit per component --- */
prev = sa_state.previous_torque_nm;
slew_mask = 0U;

delta = torque.x - prev.x;
if (delta > sa_config.max_slew_nm_per_cycle) {
    torque.x = prev.x + sa_config.max_slew_nm_per_cycle;
    slew_mask |= 1U;
} else if (delta < -sa_config.max_slew_nm_per_cycle) {
    torque.x = prev.x - sa_config.max_slew_nm_per_cycle;
    slew_mask |= 1U;
} else {
    /* no slew limiting on x */
}

delta = torque.y - prev.y;
if (delta > sa_config.max_slew_nm_per_cycle) {
    torque.y = prev.y + sa_config.max_slew_nm_per_cycle;
    slew_mask |= 2U;
} else if (delta < -sa_config.max_slew_nm_per_cycle) {
    torque.y = prev.y - sa_config.max_slew_nm_per_cycle;
    slew_mask |= 2U;
} else {
    /* no slew limiting on y */
}

delta = torque.z - prev.z;
if (delta > sa_config.max_slew_nm_per_cycle) {
    torque.z = prev.z + sa_config.max_slew_nm_per_cycle;
    slew_mask |= 4U;
} else if (delta < -sa_config.max_slew_nm_per_cycle) {
    torque.z = prev.z - sa_config.max_slew_nm_per_cycle;
    slew_mask |= 4U;
} else {
    /* no slew limiting on z */
}

/* --- step 10: publish --- */
sa_state.mode = mode;
sa_state.previous_torque_nm = torque;

sa_output.mode = mode;
sa_output.good_samples = sa_state.good_samples;
sa_output.bad_samples = sa_state.bad_samples;
sa_output.coast_samples = sa_state.coast_samples;
sa_output.error_rad = angle;
sa_output.rotation_axis = axis;
sa_output.torque_nm = torque;
sa_output.slew_mask = slew_mask;
